<?php
require_once __DIR__.'/includes/auth.php';require_role('Administrator');$action=page_param('action');$userId=(int)($_GET['user_id']??0);$from=page_param('from');$to=page_param('to');$where=['1=1'];$params=[];if($action!==''){$where[]='l.action=?';$params[]=$action;}if($userId){$where[]='l.user_id=?';$params[]=$userId;}if($from!==''){$where[]='DATE(l.created_at)>=?';$params[]=$from;}if($to!==''){$where[]='DATE(l.created_at)<=?';$params[]=$to;}$sqlWhere=implode(' AND ',$where);$count=db()->prepare("SELECT COUNT(*) FROM activity_logs l WHERE $sqlWhere");$count->execute($params);$total=(int)$count->fetchColumn();$per=50;$page=max(1,(int)($_GET['page']??1));$offset=($page-1)*$per;$stmt=db()->prepare("SELECT l.*,u.name user_name,u.email FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id WHERE $sqlWhere ORDER BY l.created_at DESC LIMIT $per OFFSET $offset");$stmt->execute($params);$logs=$stmt->fetchAll();$actions=db()->query('SELECT DISTINCT action FROM activity_logs ORDER BY action')->fetchAll(PDO::FETCH_COLUMN);$users=db()->query('SELECT id,name FROM users ORDER BY name')->fetchAll();$pageTitle='Activity logs';$pageSubtitle='An auditable record of important system actions';require __DIR__.'/includes/header.php';?>
<div class="card mb-4"><div class="card-body"><form class="row g-2 align-items-end"><div class="col-md-3"><label class="form-label small">Action</label><select class="form-select" name="action"><option value="">All actions</option><?php foreach($actions as $a):?><option <?=$action===$a?'selected':''?>><?=e($a)?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label small">User</label><select class="form-select" name="user_id"><option value="">All users</option><?php foreach($users as $row):?><option value="<?=$row['id']?>" <?=$userId===$row['id']?'selected':''?>><?=e($row['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label small">From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="col-md-2"><label class="form-label small">To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="col-md-2"><button class="btn btn-primary w-100">Filter</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Date/time</th><th>User</th><th>Action</th><th>Description</th><th>IP address</th></tr></thead><tbody><?php foreach($logs as $row):?><tr><td class="text-nowrap"><?=e(date('M j, Y g:i:s A',strtotime($row['created_at'])))?></td><td><?=e($row['user_name']??'System')?><small class="d-block text-muted"><?=e($row['email']??'')?></small></td><td><span class="badge text-bg-light"><?=e($row['action'])?></span></td><td><?=e($row['description'])?></td><td><code><?=e($row['ip_address'])?></code></td></tr><?php endforeach;?></tbody></table></div></div><?php $pages=(int)ceil($total/$per);if($pages>1):?><nav class="mt-4"><ul class="pagination justify-content-center"><?php for($p=1;$p<=$pages;$p++):?><li class="page-item <?=$p===$page?'active':''?>"><a class="page-link" href="?<?=e(http_build_query(array_merge($_GET,['page'=>$p])))?>"><?=$p?></a></li><?php endfor;?></ul></nav><?php endif;?>
<?php require __DIR__.'/includes/footer.php';?>

